// Batch 7 / W5 — page titles/descriptions for the tarot card pages. The prerender reads the
// same values from ./tarotMeta.json (generated by `npx tsx scripts/gen-tarot-meta.mts`);
// tarotCards.test.ts fails if the JSON drifts from this function.
import { TAROT_CARDS, type TarotCardEntry } from './index';

export const TAROT_INDEX_META = {
  title: 'All 78 Tarot Card Meanings — Upright & Reversed | BornClock',
  description: 'Every tarot card explained: the 22 Major Arcana and 56 Minor Arcana (Wands, Cups, Swords, Pentacles) — upright and reversed meanings, love, career, money and yes/no, from A. E. Waite (1910).',
};

function firstSentence(s: string): string {
  const m = s.match(/^.*?[.!?](\s|$)/);
  return (m ? m[0] : s).trim();
}

export function tarotCardTitle(card: TarotCardEntry): string {
  return `${card.name} Tarot Meaning — Upright & Reversed | BornClock`;
}

export function tarotCardDescription(card: TarotCardEntry): string {
  return `${firstSentence(card.answer)} Upright, reversed, love, career, money and yes/no — after A. E. Waite (1910).`;
}

export function tarotMetaMap(): Record<string, { title: string; description: string }> {
  const out: Record<string, { title: string; description: string }> = { '/tarot/cards': TAROT_INDEX_META };
  for (const c of TAROT_CARDS) out[`/tarot/cards/${c.slug}`] = { title: tarotCardTitle(c), description: tarotCardDescription(c) };
  return out;
}
